--   3. ADD FOREIGN KEY ... NOT VALID                   -- brief SHARE ROW EXCLUSIVE, retried with short lock_timeout
--   4. VALIDATE CONSTRAINT on the FK                   -- SHARE UPDATE EXCLUSIVE: no DML or read blocking
--   5. SET NOT NULL                                    -- brief ACCESS EXCLUSIVE, retried; no table scan because
--                                                      --   the validated CHECK from step 2 proves no NULLs
--
-- Every lock that can conflict with live traffic is taken with a short lock_timeout
-- and retried, so no application transaction waits long behind this script.
-- Every step is idempotent.

-- ---------------------------------------------------------------------------
-- Step 1: helper CHECK constraint, NOT VALID (no table scan)
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_deadline timestamptz := clock_timestamp() + interval '45 seconds';
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'orders'::regclass
      AND conname = 'orders_customer_id_nn_chk'
  ) THEN
    RETURN;
  END IF;

  LOOP
    BEGIN
      SET LOCAL lock_timeout = '60ms';
      ALTER TABLE orders
        ADD CONSTRAINT orders_customer_id_nn_chk
        CHECK (customer_id IS NOT NULL) NOT VALID;
      RETURN;
    EXCEPTION
      WHEN lock_not_available OR deadlock_detected THEN
        IF clock_timestamp() > v_deadline THEN
          RAISE;
        END IF;
    END;
    PERFORM pg_sleep(0.15);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------
-- Step 2: validate the CHECK. Scans orders but does not block DML or reads.
-- ---------------------------------------------------------------------------
ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_nn_chk;

-- ---------------------------------------------------------------------------
-- Step 3: add the foreign key NOT VALID (catalog change only, no scan)
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_deadline timestamptz := clock_timestamp() + interval '45 seconds';
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'orders'::regclass
      AND conname = 'orders_customer_id_fkey'
  ) THEN
    RETURN;
  END IF;

  LOOP
    BEGIN
      SET LOCAL lock_timeout = '60ms';
      ALTER TABLE orders
        ADD CONSTRAINT orders_customer_id_fkey
        FOREIGN KEY (customer_id) REFERENCES customers(id) NOT VALID;
      RETURN;
    EXCEPTION
      WHEN lock_not_available OR deadlock_detected THEN
        IF clock_timestamp() > v_deadline THEN
          RAISE;
        END IF;
    END;
    PERFORM pg_sleep(0.15);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------
-- Step 4: validate the FK. Uses SHARE UPDATE EXCLUSIVE, so app DML continues.
-- ---------------------------------------------------------------------------
ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_fkey;

-- ---------------------------------------------------------------------------
-- Step 5: SET NOT NULL. The validated CHECK lets PostgreSQL skip the scan,
-- so the ACCESS EXCLUSIVE hold is only catalog work.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_deadline timestamptz := clock_timestamp() + interval '45 seconds';
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'orders'::regclass
      AND attname = 'customer_id'
      AND attnotnull
      AND NOT attisdropped
  ) THEN
    RETURN;
  END IF;

  LOOP
    BEGIN
      SET LOCAL lock_timeout = '60ms';
      ALTER TABLE orders ALTER COLUMN customer_id SET NOT NULL;
      RETURN;
    EXCEPTION
      WHEN lock_not_available OR deadlock_detected THEN
        IF clock_timestamp() > v_deadline THEN
          RAISE;
        END IF;
    END;
    PERFORM pg_sleep(0.15);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------
-- Final verification of the ticket's end state
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'orders'::regclass
      AND attname = 'customer_id'
      AND attnotnull
      AND NOT attisdropped
  ) THEN
    RAISE EXCEPTION 'C2 verification failed: orders.customer_id is not NOT NULL';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'orders'::regclass
      AND contype = 'f'
      AND convalidated
      AND confrelid = 'customers'::regclass
      AND conname = 'orders_customer_id_fkey'
  ) THEN
    RAISE EXCEPTION 'C2 verification failed: validated FK orders -> customers(id) missing';
  END IF;
END
$$;
